        {
          "id": "alg-dyadic-square-root-bisection",
          "kind": "algorithm",
          "title": "Exact dyadic bisection for square-root endpoints",
          "deps": [
            "def-dyadic-floating-point-format-and-directed-rounding",
            "lem-nonnegative-square-root-exists-and-unique"
          ],
          "statement": "Input: a nonnegative exact dyadic rational $x$ and integer request $n\\ge1$.\nOutput: an exact dyadic lower and upper bound for $\\sqrt{x}$; no finite\nstorage format is needed by this procedure.\n\n1. If $x=0$, return $[0,0]$.\n2. Otherwise determine the unique integer $j$ with $2^j\\le x<2^{j+1}$ from the\n   exact dyadic representation, put $m=\\lfloor j/2\\rfloor$ and\n   $\\delta=2^{m-n}$.\n3. Set integer indices $L=0$ and $U=2^{n+1}$. While $U-L>1$, put\n   $Q=\\lfloor(L+U)/2\\rfloor$. If $(Q\\delta)^2\\le x$, replace $L$ by $Q$;\n   otherwise replace $U$ by $Q$.\n4. Return the exact dyadic pair $[L\\delta,U\\delta]$. A caller that stores\n   these endpoints in a selected finite format must separately round the\n   lower endpoint down and the upper endpoint up, propagating the resulting\n   `subnormal` or `overflow` status.\n\nAll comparisons and multiplications in the loop are exact integer/dyadic\noperations.",
          "dependency_level": 2,
          "justified_by": [
            "thm-dyadic-square-root-bisection-encloses"
          ],
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "sources": {
            "references": [
